void reset_comm(void)
{
    settingscomm_state_param_t comm_state;
    s32             ret;

    comm_state.auto_redial_state = 0;
    ret                 = aic_md_write(MD_ID_SETTING_COMM,sizeof(settingscomm_state_param_t),&comm_state);

    if (ret) {
        APP_LOGI("reset_comm read net cfg error 0x%x\n",ret);
        }
}

unsigned char get_auto_redial_status(void)
{
    settingscomm_state_param_t comm_state;
    s32 ret;

    ret = aic_md_read(MD_ID_SETTING_COMM,sizeof(settingscomm_state_param_t),&comm_state);

    if (ret) {
        APP_LOGI("reset_comm read net cfg error 0x%x\n",ret);
        }

    return comm_state.auto_redial_state;
}

